import { CSSProperties, useId } from 'react';

interface IIcons {
  style?: CSSProperties;
  rotate?: number;
  spin?: boolean;
  className?: string;
}

// Custom Icon component to replace Ant Design Icon
interface CustomIconProps {
  component: React.ComponentType;
  style?: CSSProperties;
  rotate?: number;
  spin?: boolean;
  className?: string;
}

interface LikeActiveIconProps extends IIcons {
  animate?: boolean;
}

function Icon({ component: Component, style, rotate, spin, className }: CustomIconProps) {
  const iconStyle: CSSProperties = {
    ...style,
    transform: rotate ? `rotate(${rotate}deg)` : undefined,
    animation: spin ? 'spin 1s linear infinite' : undefined
  };

  return (
    <span className={className} style={iconStyle}>
      <Component />
    </span>
  );
}

